Field.Text:
// 1. Initial Variables
stringVar array Units := ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
stringVar array Tens := ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
stringVar array Scales := ["", "Thousand", "Million", "Billion"];

// แปลงค่าเงินเป็น String และจัดการทศนิยม
stringVar fullAmount := ToText({Bank_Receipt.DocTotalFC}, 2, ""); 
fullAmount := replace(fullAmount, ",", "");

stringVar array parts := Split(fullAmount, ".");
stringVar wholePart := parts[1];
stringVar decimalPart := parts[2];

// --- ส่วนของ Baht ---
stringVar result := "";
numberVar n := Val(wholePart);
numberVar i := 1;

if n = 0 then 
    result := "Zero"
else (
    while n > 0 do (
        numberVar chunk := n mod 1000;
        if chunk > 0 then (
            stringVar chunkText := "";
            numberVar h := Int(chunk / 100);
            numberVar t := chunk mod 100;

            if h > 0 then 
                chunkText := Units[h + 1] + " Hundred ";

            if t > 0 then (
                if t < 20 then 
                    chunkText := chunkText + Units[t + 1]
                else (
                    chunkText := chunkText + Tens[Int(t / 10) + 1];
                    if (t mod 10) > 0 then 
                        chunkText := chunkText + "-" + Units[(t mod 10) + 1];
                )
            );

            result := CStr(chunkText) + " " + CStr(Scales[i]) + " " + CStr(result);
        );
        n := Int(n / 1000);
        i := i + 1;
        result := result; // <-- เพิ่มบรรทัดนี้ เพื่อบังคับให้ Loop คืนค่าเป็น String
    );
    result; // <-- เพิ่มบรรทัดนี้ เพื่อให้ Block Else ทั้งหมดคืนค่าเป็น String
);

// --- ส่วนของ Satang ---
stringVar centsText := "";
numberVar cents := Val(decimalPart);
if cents > 0 then (
    if cents < 20 then 
        centsText := Units[cents + 1]
    else (
        centsText := Tens[Int(cents / 10) + 1];
        if (cents mod 10) > 0 then 
            centsText := centsText + "-" + Units[(cents mod 10) + 1];
    )
);

// --- สรุปผล ---
stringVar finalOutput := "";
finalOutput := Trim(result) + " Dollars";

if Trim(centsText) <> "" then
    finalOutput := finalOutput + " and " + Trim(centsText) + " cents"
else
    finalOutput := finalOutput + " Only";

// ป้องกัน Error กรณี String ว่างก่อนใช้ Uppercase
if Len(finalOutput) > 0 then
    Uppercase(Left(finalOutput, 1)) + Mid(finalOutput, 2)
else
    "";

//=========================================================
// @AmountToWordsEng - Convert number to English words
// Multi-currency: USD, THB, EUR, GBP, JPY, CNY, SGD, MYR, LAK, VND, AUD, HKD
//=========================================================

// ===== Inputs =====
NumberVar nAmount   := {Bank_Receipt.DocTotal};
StringVar sCurrency := {Bank_Receipt.DocCurr};

// ===== Variable declarations (all at top) =====
StringVar  sMajor    := "";
StringVar  sMajors   := "";
StringVar  sMinor    := "";
StringVar  sMinors   := "";
BooleanVar bHasMinor := True;

NumberVar nAbs  := 0;
NumberVar nInt  := 0;
NumberVar nDec  := 0;
NumberVar nWork := 0;
NumberVar nGrp  := 0;
NumberVar nH    := 0;
NumberVar nR    := 0;
NumberVar nTen  := 0;
NumberVar nOne  := 0;

StringVar sIntWords := "";
StringVar sDecWords := "";
StringVar sResult   := "";
StringVar sNeg      := "";

StringVar Array aOnes := ["", "One", "Two", "Three", "Four", "Five",
                          "Six", "Seven", "Eight", "Nine", "Ten",
                          "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen",
                          "Sixteen", "Seventeen", "Eighteen", "Nineteen"];

StringVar Array aTens := ["", "", "Twenty", "Thirty", "Forty", "Fifty",
                          "Sixty", "Seventy", "Eighty", "Ninety"];

// ===== Currency mapping =====
Select UCase(sCurrency)
    Case "USD" :  (sMajor := "Dollar";   sMajors := "Dollars";   sMinor := "Cent";    sMinors := "Cents";   bHasMinor := True)
    Case "THB" :  (sMajor := "Baht";     sMajors := "Baht";      sMinor := "Satang";  sMinors := "Satang";  bHasMinor := True)
    Case "EUR" :  (sMajor := "Euro";     sMajors := "Euros";     sMinor := "Cent";    sMinors := "Cents";   bHasMinor := True)
    Case "GBP" :  (sMajor := "Pound";    sMajors := "Pounds";    sMinor := "Penny";   sMinors := "Pence";   bHasMinor := True)
    Case "JPY" :  (sMajor := "Yen";      sMajors := "Yen";       sMinor := "";        sMinors := "";        bHasMinor := False)
    Case "CNY" :  (sMajor := "Yuan";     sMajors := "Yuan";      sMinor := "Fen";     sMinors := "Fen";     bHasMinor := True)
    Case "SGD" :  (sMajor := "Dollar";   sMajors := "Dollars";   sMinor := "Cent";    sMinors := "Cents";   bHasMinor := True)
    Case "MYR" :  (sMajor := "Ringgit";  sMajors := "Ringgit";   sMinor := "Sen";     sMinors := "Sen";     bHasMinor := True)
    Case "LAK" :  (sMajor := "Kip";      sMajors := "Kip";       sMinor := "";        sMinors := "";        bHasMinor := False)
    Case "VND" :  (sMajor := "Dong";     sMajors := "Dong";      sMinor := "";        sMinors := "";        bHasMinor := False)
    Case "AUD" :  (sMajor := "Dollar";   sMajors := "Dollars";   sMinor := "Cent";    sMinors := "Cents";   bHasMinor := True)
    Case "HKD" :  (sMajor := "Dollar";   sMajors := "Dollars";   sMinor := "Cent";    sMinors := "Cents";   bHasMinor := True)
    Case "DKK" :  (sMajor := "Krone";    sMajors := "Krone";     sMinor := "Øre";     sMinors := "Øre";     bHasMinor := True)
    Case "SEK" :  (sMajor := "Krona";    sMajors := "Kronas";    sMinor := "Öre";     sMinors := "Öre";     bHasMinor := True)
    Case "NOK" :  (sMajor := "Krone";    sMajors := "Kroner";    sMinor := "Øre";     sMinors := "Øre";     bHasMinor := True)
    Case "CHF" :  (sMajor := "Franc";    sMajors := "Francs";    sMinor := "Centime"; sMinors := "Centimes";bHasMinor := True)
    Case "CAD" :  (sMajor := "Dollar";   sMajors := "Dollars";   sMinor := "Cent";    sMinors := "Cents";   bHasMinor := True)
    Case "NZD" :  (sMajor := "Dollar";   sMajors := "Dollars";   sMinor := "Cent";    sMinors := "Cents";   bHasMinor := True)
    Case "KRW" :  (sMajor := "Won";      sMajors := "Won";       sMinor := "";        sMinors := "";        bHasMinor := False)
    Case "TWD" :  (sMajor := "Dollar";   sMajors := "Dollars";   sMinor := "Cent";    sMinors := "Cents";   bHasMinor := True)
    Case "INR" :  (sMajor := "Rupee";    sMajors := "Rupees";    sMinor := "Paisa";   sMinors := "Paise";   bHasMinor := True)
    Case "IDR" :  (sMajor := "Rupiah";   sMajors := "Rupiah";    sMinor := "Sen";     sMinors := "Sen";     bHasMinor := True)
    Case "PHP" :  (sMajor := "Peso";     sMajors := "Pesos";     sMinor := "Centavo"; sMinors := "Centavos";bHasMinor := True)
    Case "MMK" :  (sMajor := "Kyat";     sMajors := "Kyats";     sMinor := "Pya";     sMinors := "Pyas";    bHasMinor := True)
    Case "KHR" :  (sMajor := "Riel";     sMajors := "Riels";     sMinor := "Sen";     sMinors := "Sen";     bHasMinor := True)
    Case "AED" :  (sMajor := "Dirham";   sMajors := "Dirhams";   sMinor := "Fils";    sMinors := "Fils";    bHasMinor := True)
    Case "SAR" :  (sMajor := "Riyal";    sMajors := "Riyals";    sMinor := "Halala";  sMinors := "Halalas"; bHasMinor := True)
    Case "ZAR" :  (sMajor := "Rand";     sMajors := "Rand";      sMinor := "Cent";    sMinors := "Cents";   bHasMinor := True)
    Case "RUB" :  (sMajor := "Ruble";    sMajors := "Rubles";    sMinor := "Kopeck";  sMinors := "Kopecks"; bHasMinor := True)
    Default    :  (sMajor := sCurrency;  sMajors := sCurrency;   sMinor := "Cent";    sMinors := "Cents";   bHasMinor := True)
;

// ===== Split integer / decimal =====
nAbs := Abs(nAmount);
nInt := Truncate(nAbs);
nDec := Round((nAbs - nInt) * 100);
If nDec = 100 Then (nInt := nInt + 1; nDec := 0);

nWork := nInt;

// ----- Trillions -----
nGrp  := Truncate(nWork / 1000000000000);
nWork := nWork - nGrp * 1000000000000;
If nGrp > 0 Then (
    nH := Truncate(nGrp / 100);
    nR := nGrp - nH * 100;
    If nH > 0 Then sIntWords := sIntWords + aOnes[nH + 1] + " Hundred ";
    If nR >= 20 Then (
        sIntWords := sIntWords + aTens[Truncate(nR / 10) + 1];
        If nR Mod 10 > 0 Then sIntWords := sIntWords + "-" + aOnes[(nR Mod 10) + 1];
        sIntWords := sIntWords + " "
    ) Else If nR > 0 Then (
        sIntWords := sIntWords + aOnes[nR + 1] + " "
    );
    sIntWords := sIntWords + "Trillion "
);

// ----- Billions -----
nGrp  := Truncate(nWork / 1000000000);
nWork := nWork - nGrp * 1000000000;
If nGrp > 0 Then (
    nH := Truncate(nGrp / 100);
    nR := nGrp - nH * 100;
    If nH > 0 Then sIntWords := sIntWords + aOnes[nH + 1] + " Hundred ";
    If nR >= 20 Then (
        sIntWords := sIntWords + aTens[Truncate(nR / 10) + 1];
        If nR Mod 10 > 0 Then sIntWords := sIntWords + "-" + aOnes[(nR Mod 10) + 1];
        sIntWords := sIntWords + " "
    ) Else If nR > 0 Then (
        sIntWords := sIntWords + aOnes[nR + 1] + " "
    );
    sIntWords := sIntWords + "Billion "
);

// ----- Millions -----
nGrp  := Truncate(nWork / 1000000);
nWork := nWork - nGrp * 1000000;
If nGrp > 0 Then (
    nH := Truncate(nGrp / 100);
    nR := nGrp - nH * 100;
    If nH > 0 Then sIntWords := sIntWords + aOnes[nH + 1] + " Hundred ";
    If nR >= 20 Then (
        sIntWords := sIntWords + aTens[Truncate(nR / 10) + 1];
        If nR Mod 10 > 0 Then sIntWords := sIntWords + "-" + aOnes[(nR Mod 10) + 1];
        sIntWords := sIntWords + " "
    ) Else If nR > 0 Then (
        sIntWords := sIntWords + aOnes[nR + 1] + " "
    );
    sIntWords := sIntWords + "Million "
);

// ----- Thousands -----
nGrp  := Truncate(nWork / 1000);
nWork := nWork - nGrp * 1000;
If nGrp > 0 Then (
    nH := Truncate(nGrp / 100);
    nR := nGrp - nH * 100;
    If nH > 0 Then sIntWords := sIntWords + aOnes[nH + 1] + " Hundred ";
    If nR >= 20 Then (
        sIntWords := sIntWords + aTens[Truncate(nR / 10) + 1];
        If nR Mod 10 > 0 Then sIntWords := sIntWords + "-" + aOnes[(nR Mod 10) + 1];
        sIntWords := sIntWords + " "
    ) Else If nR > 0 Then (
        sIntWords := sIntWords + aOnes[nR + 1] + " "
    );
    sIntWords := sIntWords + "Thousand "
);

// ----- Hundreds (last group) -----
nGrp := nWork;
If nGrp > 0 Then (
    nH := Truncate(nGrp / 100);
    nR := nGrp - nH * 100;
    If nH > 0 Then sIntWords := sIntWords + aOnes[nH + 1] + " Hundred ";
    If nR >= 20 Then (
        sIntWords := sIntWords + aTens[Truncate(nR / 10) + 1];
        If nR Mod 10 > 0 Then sIntWords := sIntWords + "-" + aOnes[(nR Mod 10) + 1]
    ) Else If nR > 0 Then (
        sIntWords := sIntWords + aOnes[nR + 1]
    )
);

If nInt = 0 Then sIntWords := "Zero";
sIntWords := Trim(sIntWords);

// ===== Decimal part =====
If nDec > 0 Then (
    If nDec < 20 Then
        sDecWords := aOnes[nDec + 1]
    Else (
        nTen := Truncate(nDec / 10);
        nOne := nDec - nTen * 10;
        sDecWords := aTens[nTen + 1];
        If nOne > 0 Then sDecWords := sDecWords + "-" + aOnes[nOne + 1]
    )
);

// ===== Build final result =====
If nAmount < 0 Then sNeg := "Minus ";

If bHasMinor Then (
    If nDec > 0 Then
        sResult := sNeg + sIntWords + " " +
                   (If nInt = 1 Then sMajor Else sMajors) +
                   " and " + sDecWords + " " +
                   (If nDec = 1 Then sMinor Else sMinors) + " Only"
    Else
        sResult := sNeg + sIntWords + " " +
                   (If nInt = 1 Then sMajor Else sMajors) + " Only"
) Else (
    sResult := sNeg + sIntWords + " " +
               (If nInt = 1 Then sMajor Else sMajors) + " Only"
);

sResult
